const b = $input.first().json.body || $input.first().json;

if (!b.siteId) throw new Error('Missing required field: siteId');
if (!b.message) throw new Error('Missing required field: message');

const msg = b.message.toLowerCase().trim();
const actionWords = /\b(implement|create|add|build|make|fix|update|change|edit|delete|remove|install|modify|replace|refactor|style|redesign|adjust|set|configure|enable|disable|write|code)\b/;
const questionWords = /^(what|why|how|can you|could you|should|is it|explain|describe|tell me)/;
const isQuestion = questionWords.test(msg);
const isActionIntent = actionWords.test(msg) && !isQuestion;

return [{
  json: {
    siteId: b.siteId,
    conversationId: b.conversationId || null,
    userId: b.userId || 'anon',
    message: b.message.trim(),
    requestId: 'req_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
    image: b.image || null,
    images: b.images || (b.image ? [b.image] : []),
    isActionIntent,
    isQuestion
  }
}];

const inp = $('Validate & Detect Intent').item.json;
const rawSite = $input.first().json;

let site = Array.isArray(rawSite) ? rawSite[0] : (rawSite?.id ? rawSite : rawSite?.data?.[0]);
if (!site?.id) throw new Error('Site not found for siteId: ' + inp.siteId);

// Extract GitHub Token: Prefer User Token, fallback to hardcoded System Token
const SYSTEM_GITHUB_TOKEN = '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';
let githubToken = (site.access_token && site.access_token.trim()) || SYSTEM_GITHUB_TOKEN;

// Use siteKey for preview URL (subdomain-safe), fallback to site_key column or inp.siteId
const siteKey = site.site_key || inp.siteId;

const repoMatch = (site.repo_url || '').match(/github\.com\/([^/]+)\/([^/]+)/);
if (!repoMatch) throw new Error('Invalid GitHub repo URL');

const owner = repoMatch[1];
const repo = repoMatch[2].replace(/\.git$/, '');
const msg = inp.message.toLowerCase();

const fileScores = new Map();
const addFile = (file, score) => fileScores.set(file, (fileScores.get(file) || 0) + score);

if (/shop|brand|name|title|logo/.test(msg)) {
  addFile('src/components/Header.tsx', 15);
  addFile('src/app/layout.tsx', 10);
  addFile('src/components/Footer.tsx', 8);
}
if (/color|theme|style|css|dark|light/.test(msg)) {
  addFile('src/app/globals.css', 10);
  addFile('tailwind.config.ts', 7);
}
if (/header|nav|menu/.test(msg)) addFile('src/components/Header.tsx', 12);
if (/footer/.test(msg)) addFile('src/components/Footer.tsx', 10);
if (/hero/.test(msg)) addFile('src/components/Hero.tsx', 10);
if (/page|home|landing/.test(msg) || fileScores.size === 0) addFile('src/app/page.tsx', 10);

const sortedFiles = [...fileScores.entries()].sort((a, b) => b[1] - a[1]).slice(0, 4).map(([f]) => f);
if (sortedFiles.length === 0) sortedFiles.push('src/app/page.tsx');

return [{
  json: {
    ...inp,
    site: { id: siteKey, uuid: site.id, name: site.name || 'Unknown', repo_url: site.repo_url, branch: site.default_branch || 'main' },
    owner, repo,
    branch: site.default_branch || 'main',
    previewUrl: 'https://' + siteKey + '.preview.automatelb.com',
    filesToFetch: sortedFiles,
    fileContents: {},
    contextFiles: [],
    githubToken: githubToken
  }
}];

// Parallel file fetching with Promise.all
const ctx = $('Build Context').item.json;
const files = ctx.filesToFetch || [];
if (files.length === 0) return [{ json: { ...ctx, fileContents: {}, contextFiles: [] } }];

const results = await Promise.all(files.slice(0, 5).map(async (file) => {
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.github.com/repos/' + ctx.owner + '/' + ctx.repo + '/contents/' + file + '?ref=' + (ctx.branch || 'main'),
      headers: {
        'Authorization': 'Bearer ' + ctx.githubToken,
        'Accept': 'application/vnd.github.v3.raw'
      },
      timeout: 10000
    });
    return { path: file, content: typeof response === 'string' ? response : JSON.stringify(response), success: true };
  } catch (e) {
    return { path: file, error: e.message, success: false };
  }
}));

const fileContents = {};
const contextFiles = [];
for (const r of results.filter(r => r.success)) {
  fileContents[r.path] = r.content.length > 3000 ? r.content.substring(0, 3000) + '\n// ...truncated' : r.content;
  contextFiles.push(r.path);
}

return [{ json: { ...ctx, fileContents, contextFiles, _parallelFetch: true } }];

// Merge Files - now Prepare Fetch does parallel fetching directly
const items = $input.all();
const firstItem = items[0]?.json;

// If Prepare Fetch already did parallel fetching, just pass through
if (firstItem?._parallelFetch || firstItem?.fileContents) {
  return [{ json: firstItem }];
}

// Fallback: Old flow where Fetch Files HTTP node was used
const prepItems = $('Prepare Fetch').all();
const ctx = prepItems[0]?.json?._ctx || prepItems[0]?.json || firstItem;
if (!ctx) return [{ json: { error: 'Lost context', fileContents: {}, contextFiles: [] } }];

const fileContents = ctx.fileContents || {};
const contextFiles = ctx.contextFiles || [];

for (let i = 0; i < items.length; i++) {
  const item = items[i].json;
  const path = prepItems[i]?.json?.currentFile || item.path;
  if (!path || fileContents[path]) continue;
  if (item.content) {
    try {
      const decoded = Buffer.from(item.content, 'base64').toString('utf8');
      fileContents[path] = decoded.length > 3000 ? decoded.substring(0, 3000) + '\n// ...truncated' : decoded;
      contextFiles.push(path);
    } catch (e) {}
  }
}

return [{ json: { ...ctx, fileContents, contextFiles } }];

// Fetch recent memory for this project from Supabase
const ctx = $input.item.json;
const siteId = ctx.site?.uuid;
const requestId = ctx.requestId || 'unknown';
const conversationId = ctx.conversationId || null;

if (!siteId) {
  return [{ json: { ...ctx, memoryContext: 'First request.' } }];
}

// Insert initial thinking step
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://jjrbnjubjiswvxeradzw.supabase.co/rest/v1/thinking_steps',
    headers: {
      'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: JSON.stringify({
      request_id: requestId,
      site_id: siteId,
      conversation_id: conversationId,
      step_number: 1,
      tool_name: 'analyze',
      status: 'running',
      message: 'Analyzing...',
      details: { message: ctx.message }
    }),
    timeout: 5000
  });
} catch (e) {}

try {
  let memoryUrl = 'https://jjrbnjubjiswvxeradzw.supabase.co/rest/v1/agent_memory?project_id=eq.' + siteId;
  if (conversationId) {
    memoryUrl += '&or=(session_id.eq.' + conversationId + ',session_id.is.null)';
  }
  memoryUrl += '&order=created_at.desc&limit=5';

  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: memoryUrl,
    headers: {
      'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4'
    },
    timeout: 10000
  });

  let memoryContext = 'First request.';
  if (Array.isArray(response) && response.length > 0) {
    // Ultra-compressed format: msg→[files]→result
    memoryContext = response.reverse().map(function(e) {
      const d = e.content_json || {};
      const msg = (d.message || '').slice(0, 50);
      const files = (d.filesModified || []).concat(d.filesCreated || []).map(f => f.split('/').pop()).join(',');
      const result = (d.summary || 'ok').slice(0, 60);
      return msg + '→[' + files + ']→' + result;
    }).join('\n');
  }

  return [{ json: { ...ctx, memoryContext: memoryContext } }];
} catch (e) {
  return [{ json: { ...ctx, memoryContext: 'First request.' } }];
}

const rawInput = $fromAI('query', 'Directory path', 'string') || '';
let dir = rawInput.trim() || 'src';

if (dir.startsWith('{')) {
  try { const p = JSON.parse(dir); dir = p.path || p.directory || 'src'; } catch {}
}

const ctx = $('Merge Files')?.item?.json || {};
const owner = ctx.owner;
const repo = ctx.repo;
const branch = ctx.branch || 'main';
const githubToken = ctx.githubToken;

if (!owner || !repo || !githubToken) return 'Error: No repository context';

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.github.com/repos/' + owner + '/' + repo + '/contents/' + dir + '?ref=' + branch,
    headers: {
      'Authorization': 'Bearer ' + githubToken,
      'Accept': 'application/vnd.github+json'
    },
    timeout: 15000
  });
  if (Array.isArray(response)) {
    return response.map(f => f.path + (f.type === 'dir' ? '/' : '')).join('\n');
  }
  return JSON.stringify(response);
} catch (e) {
  return 'Error listing files: ' + e.message;
}

const rawInput = $fromAI('query');
const filePath = (typeof rawInput === 'string' ? rawInput : JSON.stringify(rawInput)).trim();

if (!filePath) return 'Error: File path required';

const ctx = $('Merge Files')?.item?.json || {};
const siteId = ctx.site?.id;
const githubToken = ctx.githubToken;
const requestId = ctx.requestId || 'req';
const siteUuid = ctx.site?.uuid || siteId;

if (!siteId) return 'Error: No site context';

// Emit progress
try { await this.helpers.httpRequest({ method: 'POST', url: 'https://jjrbnjubjiswvxeradzw.supabase.co/rest/v1/thinking_steps', headers: { 'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4', 'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4', 'Content-Type': 'application/json', 'Prefer': 'return=minimal' }, body: JSON.stringify({ request_id: requestId, site_id: siteUuid, step_number: Date.now() % 100000, tool_name: 'read_file', status: 'running', message: 'Reading ' + filePath.split('/').pop(), details: { path: filePath } }), timeout: 3000 }); } catch(e) {}

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://preview-orchestrator.fly.dev/preview/read',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ siteId, filePath, githubToken }),
    timeout: 30000,
    json: true,
    ignoreHttpStatusErrors: true,
    returnFullResponse: true
  });

  const body = response.body;
  if (response.statusCode >= 400 || (body && !body.success && !body.ok)) {
     return 'Error: Orchestrator ' + response.statusCode + ' - ' + JSON.stringify(body);
  }

  return body.content || 'Error: No content returned';
} catch (e) {
  return 'Error: Exception - ' + e.message;
}

// Use $fromAI() WITHOUT the type parameter (third arg causes readonly errors)
const rawInput = $fromAI('query');
const input = (typeof rawInput === 'string' ? rawInput : JSON.stringify(rawInput)).trim();

const idx = input.indexOf('|||');
if (idx === -1) return 'Error: Invalid format. Use: filePath|||fileContent';

const filePath = input.substring(0, idx).trim();
const content = input.substring(idx + 3);
if (!filePath) return 'Error: File path required';

const ctx = $('Merge Files')?.item?.json || {};
const siteId = ctx.site?.id;
const githubToken = ctx.githubToken;
const requestId = ctx.requestId || 'req';
const siteUuid = ctx.site?.uuid || siteId;

if (!siteId) return 'Error: No site context';

// Emit progress start
try { await this.helpers.httpRequest({ method: 'POST', url: 'https://jjrbnjubjiswvxeradzw.supabase.co/rest/v1/thinking_steps', headers: { 'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4', 'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4', 'Content-Type': 'application/json', 'Prefer': 'return=minimal' }, body: JSON.stringify({ request_id: requestId, site_id: siteUuid, step_number: Date.now() % 100000, tool_name: 'write_file', status: 'running', message: 'Writing ' + filePath.split('/').pop(), details: { path: filePath, lines: content.split('\n').length } }), timeout: 3000 }); } catch(e) {}

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://preview-orchestrator.fly.dev/preview/write',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ siteId, filePath, content, githubToken }),
    timeout: 30000,
    json: true,
    ignoreHttpStatusErrors: true,
    returnFullResponse: true
  });

  const body = response.body;
  if (response.statusCode >= 400 || (body && !body.success && !body.ok)) {
     const debugInfo = { status: response.statusCode, sent: { siteId, filePath, contentLen: content?.length }, response: body };
     return 'Error: Orchestrator ' + response.statusCode + ' - ' + JSON.stringify(debugInfo);
  }

  return JSON.stringify({ success: true, file: filePath, action: 'created' });
} catch (e) {
  return 'Error: Exception - ' + e.message;
}

const rawInput = $fromAI('query');
const input = (typeof rawInput === 'string' ? rawInput : JSON.stringify(rawInput)).trim();

const firstSep = input.indexOf('|||');
if (firstSep === -1) return 'Error: Invalid format. Use: filePath|||searchText|||replaceText';
const secondSep = input.indexOf('|||', firstSep + 3);
if (secondSep === -1) return 'Error: Invalid format. Use: filePath|||searchText|||replaceText';

const filePath = input.substring(0, firstSep).trim();
let search = input.substring(firstSep + 3, secondSep);
let replace = input.substring(secondSep + 3);

// CRITICAL FIX: Convert escaped newlines to actual newlines
// AI agents often send \n as literal text, but we need real newlines for matching
search = search.replace(/\\n/g, '\n').replace(/\\t/g, '\t');
replace = replace.replace(/\\n/g, '\n').replace(/\\t/g, '\t');

if (!filePath || !search) return 'Error: File path and search text required';

const ctx = $('Merge Files')?.item?.json || {};
const siteId = ctx.site?.id;
const githubToken = ctx.githubToken;
const requestId = ctx.requestId || 'req';
const siteUuid = ctx.site?.uuid || siteId;

if (!siteId) return 'Error: No site context';

// Emit progress
try { await this.helpers.httpRequest({ method: 'POST', url: 'https://jjrbnjubjiswvxeradzw.supabase.co/rest/v1/thinking_steps', headers: { 'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4', 'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4', 'Content-Type': 'application/json', 'Prefer': 'return=minimal' }, body: JSON.stringify({ request_id: requestId, site_id: siteUuid, step_number: Date.now() % 100000, tool_name: 'str_replace', status: 'running', message: 'Editing ' + filePath.split('/').pop(), details: { path: filePath, searchLen: search.length, replaceLen: replace.length } }), timeout: 3000 }); } catch(e) {}

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://preview-orchestrator.fly.dev/preview/replace',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ siteId, filePath, search, replace, githubToken }),
    timeout: 30000,
    json: true,
    ignoreHttpStatusErrors: true,
    returnFullResponse: true
  });

  const body = response.body;
  if (response.statusCode >= 400 || (body && !body.success && !body.ok)) {
     // Enhanced error message that tells AI to use read_file first
     if (body?.response?.error === 'Search text not found in file') {
       return 'Error: Search text not found in file. The text you searched for does not exist exactly as written. You MUST use read_file first to see the actual content, then use the EXACT text from the file (including all whitespace, newlines, and formatting) in your search parameter. Do not guess the file content.';
     }
     const debugInfo = { status: response.statusCode, sent: { siteId, filePath, searchLen: search?.length, replaceLen: replace?.length }, response: body };
     return 'Error: Orchestrator ' + response.statusCode + ' - ' + JSON.stringify(debugInfo);
  }

  return JSON.stringify({ success: true, file: filePath, action: 'replaced' });
} catch (e) {
  return 'Error: Exception - ' + e.message;
}

